public static class Practice {
 public static void Apply(PracticeState s, string action, int value) {
  if(action=="enter"){s.Active=true;s.Subscriptions=1;s.InputEnabled=!s.Paused;}
  else if(action=="exit"){s.Active=false;s.InputEnabled=false;s.Subscriptions=0;s.LiveObjects=0;}
  else if(action=="pause"){s.Paused=true;s.InputEnabled=false;}
  else if(action=="resume"){s.Paused=false;s.InputEnabled=s.Active;}
  else if(action=="collect" && s.Active && s.InputEnabled){s.Score+=value;s.SavedScore=s.Score;}
  else if(action=="spawn" && s.Active){s.LiveObjects=1;}
  else if(action=="despawn"){s.LiveObjects=0;}
 }
}
